func marshalRole(p unsafe.Pointer) (any, error) {
	return Role(gobject.ValueFromNative(p).Enum()), nil
}

var _ gobject.GoValueInitializer = Role(0)

func (e Role) InitGoValue(v *gobject.Value) {
	v.Init(TypeRole)
	v.SetEnum(int(e))
}

